db.exec(`PRAGMA journal_mode=WAL;
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, email TEXT NOT NULL UNIQUE, username TEXT, name TEXT NOT NULL, phone TEXT NOT NULL DEFAULT '', role TEXT NOT NULL CHECK(role IN ('admin','shop_owner','delivery_partner')), salt TEXT NOT NULL, password_hash TEXT NOT NULL, shop_id INTEGER, delivery_zone TEXT NOT NULL DEFAULT '', partner_id TEXT UNIQUE, must_change_password INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS shops(id INTEGER PRIMARY KEY, name TEXT NOT NULL, locality TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', pin TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','rejected','suspended')), supports_instant_delivery INTEGER NOT NULL DEFAULT 1, supports_same_day_delivery INTEGER NOT NULL DEFAULT 1, delivery_capacity INTEGER NOT NULL DEFAULT 80, delivery_cutoff TEXT NOT NULL DEFAULT '16:00', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS customers(id INTEGER PRIMARY KEY, username TEXT NOT NULL COLLATE NOCASE UNIQUE, email TEXT UNIQUE COLLATE NOCASE, name TEXT NOT NULL, phone TEXT NOT NULL UNIQUE, pin TEXT NOT NULL, address TEXT NOT NULL DEFAULT '', latitude REAL, longitude REAL, salt TEXT NOT NULL, password_hash TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS customer_sessions(token_hash TEXT PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES customers(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_events(id INTEGER PRIMARY KEY, actor_id INTEGER REFERENCES users(id), action TEXT NOT NULL, entity TEXT NOT NULL, entity_id TEXT, details TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS guest_sessions(id INTEGER PRIMARY KEY,token_hash TEXT NOT NULL UNIQUE,name TEXT NOT NULL,phone TEXT NOT NULL,pin TEXT NOT NULL,address TEXT NOT NULL,latitude REAL,longitude REAL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS market_products(id INTEGER PRIMARY KEY,name TEXT NOT NULL,unit TEXT NOT NULL,price INTEGER NOT NULL,compare_at INTEGER,stock INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS shop_inventory(shop_id INTEGER NOT NULL REFERENCES shops(id),product_id INTEGER NOT NULL REFERENCES market_products(id),stock INTEGER NOT NULL CHECK(stock>=0),unit_price INTEGER,active INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(shop_id,product_id));
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,customer_id INTEGER REFERENCES customers(id),guest_id INTEGER REFERENCES guest_sessions(id),shop_id INTEGER NOT NULL REFERENCES shops(id),delivery_partner_user_id INTEGER REFERENCES users(id),customer_name TEXT NOT NULL,customer_phone TEXT NOT NULL,delivery_pin TEXT NOT NULL,address_snapshot TEXT NOT NULL,payment_status TEXT NOT NULL DEFAULT 'unpaid_demo' CHECK(payment_status IN ('unpaid_demo','paid','failed','refunded')),status TEXT NOT NULL,subtotal INTEGER NOT NULL,discount INTEGER NOT NULL,delivery_fee INTEGER NOT NULL,total INTEGER NOT NULL,idempotency_key TEXT NOT NULL,fulfillment_method TEXT NOT NULL DEFAULT 'instant_delivery',delivery_estimate_start_at TEXT,delivery_estimate_end_at TEXT,pickup_deadline_at TEXT,pickup_location_snapshot TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK((customer_id IS NULL)!=(guest_id IS NULL)));
CREATE TABLE IF NOT EXISTS order_items(id INTEGER PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id INTEGER NOT NULL REFERENCES market_products(id),product_name TEXT NOT NULL,unit TEXT NOT NULL,unit_price INTEGER NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),line_total INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS order_events(id INTEGER PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,actor_user_id INTEGER REFERENCES users(id),status TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS sessions_expiry_idx ON sessions(expires_at);
CREATE INDEX IF NOT EXISTS audit_created_idx ON audit_events(created_at DESC);
CREATE INDEX IF NOT EXISTS orders_shop_status_idx ON orders(shop_id,status,created_at DESC);
CREATE INDEX IF NOT EXISTS orders_partner_status_idx ON orders(delivery_partner_user_id,status,created_at DESC);
CREATE INDEX IF NOT EXISTS orders_customer_idx ON orders(customer_id,created_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS orders_customer_idem_idx ON orders(customer_id,idempotency_key) WHERE customer_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS orders_guest_idem_idx ON orders(guest_id,idempotency_key) WHERE guest_id IS NOT NULL;`);
if(!db.prepare('PRAGMA table_info(users)').all().some(column=>column.name==='username'))db.exec('ALTER TABLE users ADD COLUMN username TEXT');
for(const [column,definition] of [['phone',"TEXT NOT NULL DEFAULT ''"],['delivery_zone',"TEXT NOT NULL DEFAULT ''"],['partner_id','TEXT'],['must_change_password','INTEGER NOT NULL DEFAULT 0']])if(!db.prepare('PRAGMA table_info(users)').all().some(item=>item.name===column))db.exec(`ALTER TABLE users ADD COLUMN ${column} ${definition}`);
for(const [column,definition] of [['address',"TEXT NOT NULL DEFAULT ''"]])if(!db.prepare('PRAGMA table_info(shops)').all().some(item=>item.name===column))db.exec(`ALTER TABLE shops ADD COLUMN ${column} ${definition}`);
for(const [column,definition] of [['supports_instant_delivery','INTEGER NOT NULL DEFAULT 1'],['supports_same_day_delivery','INTEGER NOT NULL DEFAULT 1'],['delivery_capacity','INTEGER NOT NULL DEFAULT 80'],['delivery_cutoff',"TEXT NOT NULL DEFAULT '16:00'"]])if(!db.prepare('PRAGMA table_info(shops)').all().some(item=>item.name===column))db.exec(`ALTER TABLE shops ADD COLUMN ${column} ${definition}`);
for(const [column,definition] of [['unit_price','INTEGER'],['active','INTEGER NOT NULL DEFAULT 1']])if(!db.prepare('PRAGMA table_info(shop_inventory)').all().some(item=>item.name===column))db.exec(`ALTER TABLE shop_inventory ADD COLUMN ${column} ${definition}`);
for(const [column,definition] of [['fulfillment_method',"TEXT NOT NULL DEFAULT 'instant_delivery'"],['delivery_estimate_start_at','TEXT'],['delivery_estimate_end_at','TEXT'],['pickup_deadline_at','TEXT'],['pickup_location_snapshot','TEXT']])if(!db.prepare('PRAGMA table_info(orders)').all().some(item=>item.name===column))db.exec(`ALTER TABLE orders ADD COLUMN ${column} ${definition}`);
for(const [column,definition] of [['latitude','REAL'],['longitude','REAL']])if(!db.prepare('PRAGMA table_info(customers)').all().some(item=>item.name===column))db.exec(`ALTER TABLE customers ADD COLUMN ${column} ${definition}`);
db.exec('CREATE UNIQUE INDEX IF NOT EXISTS users_username_unique ON users(lower(username)) WHERE username IS NOT NULL');
